pub enum Msg {
    Ping,
    Hello(String),
}

pub const VERSION: u8 = 1;
const HELLO_VERSION: u8 = 2;

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }

    decode_hello(bytes).ok_or_else(|| "unknown".into())
}

fn compact_json(body: &str) -> Option<String> {
    let mut compact = String::new();
    let mut in_string = false;
    let mut escaped = false;
    for ch in body.chars() {
        if in_string {
            compact.push(ch);
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_string = false;
            }
        } else if ch == '"' {
            in_string = true;
            compact.push(ch);
        } else if !ch.is_whitespace() {
            compact.push(ch);
        }
    }
    if in_string || escaped {
        None
    } else {
        Some(compact)
    }
}

fn decode_hello(body: &str) -> Option<Msg> {
    let compact = compact_json(body)?;
    let prefix = format!(r#"{{"v":{},"type":"hello","message":""#, HELLO_VERSION);
    let suffix = "\"}";
    if !compact.starts_with(&prefix) || !compact.ends_with(suffix) {
        return None;
    }

    let value = &compact[prefix.len()..compact.len() - suffix.len()];
    parse_json_string_fragment(value).map(Msg::Hello)
}

fn parse_json_string_fragment(value: &str) -> Option<String> {
    let mut result = String::new();
    let mut chars = value.chars();
    while let Some(ch) = chars.next() {
        if ch != '\\' {
            result.push(ch);
            continue;
        }

        match chars.next()? {
            '"' => result.push('"'),
            '\\' => result.push('\\'),
            '/' => result.push('/'),
            'b' => result.push('\u{0008}'),
            'f' => result.push('\u{000c}'),
            'n' => result.push('\n'),
            'r' => result.push('\r'),
            't' => result.push('\t'),
            _ => return None,
        }
    }
    Some(result)
}

fn encode_json_string(value: &str) -> String {
    let mut encoded = String::new();
    for ch in value.chars() {
        match ch {
            '"' => encoded.push_str(r#"\""#),
            '\\' => encoded.push_str(r#"\\"#),
            '\n' => encoded.push_str(r#"\n"#),
            '\r' => encoded.push_str(r#"\r"#),
            '\t' => encoded.push_str(r#"\t"#),
            ch if ch.is_control() => encoded.push_str(&format!(r#"\u{:04x}"#, ch as u32)),
            ch => encoded.push(ch),
        }
    }
    encoded
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(message) => format!(
            r#"{{"v":{},"type":"hello","message":"{}"}}"#,
            HELLO_VERSION,
            encode_json_string(message)
        ),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn decodes_versioned_ping() {
        assert!(matches!(
            decode(r#"{ "version": 1, "type": "ping" }"#),
            Ok(Msg::Ping)
        ));
        assert!(matches!(
            decode(r#"{ "type": "ping", "version": 1 }"#),
            Ok(Msg::Ping)
        ));
    }

    #[test]
    fn preserves_ping_encoding() {
        assert_eq!(encode(&Msg::Ping), "ping");
        assert!(matches!(decode(&encode(&Msg::Ping)), Ok(Msg::Ping)));
    }

    #[test]
    fn decodes_v2_hello() {
        assert!(matches!(
            decode(r#"{ "v": 2, "type": "hello", "message": "world" }"#),
            Ok(Msg::Hello(message)) if message == "world"
        ));
    }

    #[test]
    fn encodes_and_roundtrips_v2_hello() {
        let msg = Msg::Hello("hello, \"world\"!".into());
        assert_eq!(
            encode(&msg),
            r#"{"v":2,"type":"hello","message":"hello, \"world\"!"}"#
        );
        assert!(matches!(decode(&encode(&msg)), Ok(Msg::Hello(message)) if message == "hello, \"world\"!"));
    }

    #[test]
    fn rejects_unknown_bodies() {
        assert!(decode(r#"{ "version": 2, "type": "ping" }"#).is_ok());
        assert!(decode(r#"{ "v": 1, "type": "hello", "message": "world" }"#).is_err());
    }
}
